// ListResourceReferences GET /v1/resource-references（content:listResourceReferences）。
// queries传递登记的查询参数；必填、类型和范围由拥有服务入口严格校验。
func (c *ContentClient) ListResourceReferences(ctx context.Context, queries ...url.Values) (json.RawMessage, error) {
	requestPath := "/v1/resource-references"
	query := url.Values{}
	for _, values := range queries {
		for key, entries := range values {
			query[key] = append(query[key], entries...)
		}
	}
	if query.Get("limit") == "" {
		query.Set("limit", "20")
	}
	if encoded := query.Encode(); encoded != "" {
		requestPath += "?" + encoded
	}
	return c.do(ctx, http.MethodGet, requestPath, nil, "")
}

